<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {localDateKey,localDayBounds} from '@/lib/businessDay'
import {useI18n} from '@/lib/i18n'
const {pick,formatDateTime}=useI18n()
type Row={id:string;invoice_number:string;invoice_date:string;cashier_name:string;patient_name:string|null;doctor_name:string|null;prescription_note:string|null;product_name:string;batch_number:string;drap:string|null;quantity:number;bonus_units:number;regulatory_snapshot:number}
const from=ref(localDateKey()),to=ref(localDateKey()),result=ref<{rows:Row[];total:number;units:number}>({rows:[],total:0,units:0}),offset=ref(0),busy=ref(false),error=ref('')
onMounted(()=>load())
async function load(reset=true){busy.value=true;error.value='';if(reset)offset.value=0;try{if(from.value>to.value)throw new Error(pick('End date must not precede start date.','آخری تاریخ ابتدائی تاریخ سے پہلے نہیں ہو سکتی۔'));const [start]=localDayBounds(from.value),[,end]=localDayBounds(to.value);result.value=await invoke('controlled_sales_report',{request:{start,end,offset:offset.value}})}catch(e){result.value={rows:[],total:0,units:0};error.value=String(e)}finally{busy.value=false}}
function page(n:number){offset.value+=100*n;void load(false)}
</script>
<template><div class="tool-terminal documents-terminal"><header class="tool-header"><div><h1>{{pick('Controlled Sales','کنٹرول شدہ ادویات کی فروخت')}}</h1><p>{{pick('Saved classification, prescription evidence and stock units','محفوظ درجہ بندی، نسخے کا حوالہ اور اسٹاک اکائیاں')}}</p></div></header><form class="commercial-filters" @submit.prevent="load()"><label>{{pick('From','سے')}}<input v-model="from" type="date" required/></label><label>{{pick('To','تک')}}<input v-model="to" :min="from" type="date" required/></label><button class="bg-primary" :disabled="busy">{{pick('Run report','رپورٹ دکھائیں')}}</button></form><p class="commercial-hint">{{pick('Operational report, not a statutory narcotics register or compliance certification. Quantities are base stock units including free units. Original sale facts remain; returns are separate records. Imported classification reflects the catalog at upgrade, not a reconstructed historical prescription.','یہ عملی رپورٹ ہے، قانونی منشیات رجسٹر یا تعمیل کی سند نہیں۔ تعداد بنیادی اسٹاک اکائیوں میں ہے، مفت اکائیوں سمیت۔ اصل فروخت برقرار رہتی ہے؛ واپسی الگ ریکارڈ ہے۔ درآمد شدہ درجہ بندی اپ گریڈ کی فہرست سے ہے، پرانا نسخہ خود سے نہیں بنایا گیا۔')}}</p><p v-if="error" role="alert" class="commercial-error">{{error}}</p><div class="commercial-table-scroll"><p v-if="busy" role="status">{{pick('Loading…','لوڈ ہو رہا ہے…')}}</p><table v-else><thead><tr><th>{{pick('Invoice / when','بل / وقت')}}</th><th>{{pick('Cashier','کیشئر')}}</th><th>{{pick('Medicine / batch / DRAP','دوا / بیچ / DRAP')}}</th><th>{{pick('Stock / free units','اسٹاک / مفت اکائیاں')}}</th><th>{{pick('Patient / doctor / prescription','مریض / ڈاکٹر / نسخہ')}}</th></tr></thead><tbody><tr v-for="r in result.rows" :key="r.id"><td>{{r.invoice_number}}<small>{{formatDateTime(r.invoice_date)}}</small><small v-if="!r.regulatory_snapshot">{{pick('Imported classification','درآمد شدہ درجہ بندی')}}</small></td><td>{{r.cashier_name}}</td><td>{{r.product_name}}<small>{{r.batch_number}}</small><small>DRAP: {{r.drap||pick('Not recorded','درج نہیں')}}</small></td><td>{{r.quantity}} / {{r.bonus_units}}</td><td>{{r.patient_name||'—'}}<small>{{r.doctor_name||'—'}}</small><small style="white-space:normal;max-width:300px;overflow-wrap:anywhere">{{r.prescription_note||'—'}}</small></td></tr><tr v-if="!result.rows.length"><td colspan="5" class="commercial-empty">{{pick('No controlled sales in this range.','اس مدت میں کنٹرول شدہ دوا کی فروخت نہیں۔')}}</td></tr></tbody></table></div><footer class="tool-summary"><div><small>{{pick('Sale lines','فروخت کی سطریں')}}</small><strong>{{result.total}}</strong></div><div><small>{{pick('Base stock units','بنیادی اسٹاک اکائیاں')}}</small><strong>{{result.units}}</strong></div><button :disabled="busy||offset===0" @click="page(-1)">{{pick('Previous','پچھلا')}}</button><button :disabled="busy||offset+100>=result.total" @click="page(1)">{{pick('Next','اگلا')}}</button></footer></div></template>
